-- 2026-10-w4 G2 動画レビュー 2 回目: A80 の情景を右下から右手が伸びる構図へ
-- A80
UPDATE quiz_stock_items q JOIN batch_sets b ON b.id = q.set_id SET q.content_fields = CAST('{"hook": "朝の指体操、いくぞ!", "hint": "指ごとに重さを変えてみろ!", "question": "片手の指は5本。ふつうに数えれば5までだ。でも数え方を工夫すると、片手だけで31まで数えられる。どうやる?", "answer": "指の立て・曲げを2進数の各けたに使う", "explanation": "親指を1、人差し指を2、中指を4、薬指を8、小指を16と決め、立てた指の値を足す。全部立てれば31。両手なら1023まで数えられるぞ。", "coach_comment": "指の使い方が天才的だ!", "tags": ["なぞなぞ", "朝の一問", "参加型"], "summary": "片手の指だけで31まで数える方法を問う定番。指に1・2・4・8・16を割り当て、立てた指の値を足す2進数の数え方。視聴者がその場で試せる参加型。", "illustration_scene": "自分の目で手元を見下ろした一人称視点の構図。画面の右下の角から自分の右手が手首から先だけ伸び、5本の指を開いた手のひらを上に向けて、真上から見下ろしている。手の下は朝日が差し込む窓辺の木の机。手の上に大きな「?」。手以外の人物は描かない。「?」以外の文字や数字は描かない。"}' AS JSON) WHERE b.set_code = 'logic-training-1' AND q.content_key = 'morning-076';
